let sharkPublicNext=0;
async function fetchJson(ex,path,options={}){if(ex==='shark'){let wait=Math.max(0,sharkPublicNext-Date.now());sharkPublicNext=Math.max(Date.now(),sharkPublicNext)+1200;if(wait)await new Promise(resolve=>setTimeout(resolve,wait))}let last;for(const base of (ex==='shark'?['/api/'+ex]:['/api/'+ex,DIRECT[ex]])){for(let attempt=0;attempt<2;attempt++){try{let r=await fetch(base+path,{cache:'no-store',signal:AbortSignal.timeout(15000),...options});if(!r.ok){let e=Error(`HTTP ${r.status}`);e.retryable=r.status===429||r.status>=500;throw e}let d=await r.json();if(d?.success===false)throw Error('Exchange returned an unsuccessful response');return d}catch(e){last=e;if(attempt===0&&(e.retryable||/timeout|network|fetch|abort/i.test(e.message))){await new Promise(resolve=>setTimeout(resolve,ex==='shark'?2000:750));continue}break}}}throw Error(`${ex==='delta'?'Delta India':'Shark'} feed unavailable (${last?.message||'network error'}).`)}
const unwrap=d=>d?.result??d?.data??d;
function normalized(raw,ex,tf,live=false){let a=unwrap(raw);if(!Array.isArray(a))throw Error('Candle response unavailable');let mapped=a.map(x=>({time:ex==='delta'?+x.time*1000:+x.startTime,open:+x.open,close:+x.close,high:+x.high,low:+x.low,volume:+x.volume})).filter(x=>Number.isFinite(x.time)&&x.open>0&&x.high>=x.open&&x.low<=x.open&&x.close>0&&x.high>=x.close&&x.low<=x.close&&x.low>0&&Number.isFinite(x.volume)&&x.volume>=0&&(live?x.time<=Date.now():x.time+SEC[tf]*1000<=Date.now()));const seen=new Map();for(const c of mapped){if(seen.has(c.time)&&JSON.stringify(seen.get(c.time))!==JSON.stringify(c)&&c.time+SEC[tf]*1000<=Date.now())throw Error('Conflicting closed candle data');seen.set(c.time,c)}let bars=[...seen.values()].sort((a,b)=>a.time-b.time);if(!bars.length||Date.now()-bars.at(-1).time>SEC[tf]*2000)throw Error('Candle feed is stale');for(let i=1;i<bars.length;i++)if(bars[i].time-bars[i-1].time!==SEC[tf]*1000)throw Error('Candle history has gaps');return bars}
async function fetchCandles(ex,symbol,tf,count,live=false){if(ex==='delta'){let end=Math.floor(Date.now()/1000),start=end-SEC[tf]*(count+3);return normalized(await fetchJson(ex,`/v2/history/candles?resolution=${tf}&symbol=${encodeURIComponent(symbol)}&start=${start}&end=${end}`),ex,tf,live)}return normalized(await fetchJson(ex,'/v1/market/klines?priceType=LAST_PRICE',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({pair:symbol,interval:tf,limit:Math.min(1000,count+3)})}),ex,tf,live)}
const closedCandleCache=new Map();
async function candles(ex,symbol,tf,count,live=false){if(live)return fetchCandles(ex,symbol,tf,count,true);let key=[ex,symbol,tf,count,Math.floor(Date.now()/(SEC[tf]*1000))].join(':');if(!closedCandleCache.has(key)){if(closedCandleCache.size>1500)closedCandleCache.clear();closedCandleCache.set(key,fetchCandles(ex,symbol,tf,count).catch(e=>{closedCandleCache.delete(key);throw e}))}return closedCandleCache.get(key)}
function setError(message){$('error').textContent=message;$('error').classList.remove('hide')}function clearError(){$('error').classList.add('hide')}
function renderListings(){let needle=$('search').value.trim().toUpperCase(),shown=listings.filter(x=>x.symbol.includes(needle)||x.base.includes(needle));$('listingCount').textContent=`${listings.length}`;$('listingStatus').textContent=`${shown.length} of ${listings.length} listed contracts`;$('listingRows').innerHTML=shown.length?shown.map(x=>`<tr><td class="coin"><button class="coin-link" data-chart="${esc(x.symbol)}">${esc(x.base)}</button><small>${esc(x.symbol)}</small></td><td>${money(x.price,x.quote)}</td><td>${compact(x.volume,x.quote)}</td><td class="${x.change>=0?'positive':'negative'}">${pct(x.change)}</td></tr>`).join(''):'<tr><td colspan="4" class="empty">No contracts match your search.</td></tr>'}
async function loadListings(){let id=++loadId;scanId++;renderScanIssues([]);resetChart();$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market';$('progress').classList.add('hide');$('coverage').textContent='';let ex=exchange(),q=market();quote=q;clearError();listings=[];results=[];$('listingCount').textContent='';$('listingStatus').textContent='Loading exchange listings…';$('listingRows').innerHTML='<tr><td colspan="4" class="empty">Loading listings…</td></tr>';$('rows').innerHTML='<tr><td colspan="8" class="empty">Run the scan for this exchange.</td></tr>';$('market').closest('.control').classList.toggle('hide',ex!=='shark');$('updated').textContent='Loading '+(ex==='delta'?'Delta India':'Shark');try{let loaded;if(ex==='delta'){let d=unwrap(await fetchJson('delta','/v2/tickers?contract_types=perpetual_futures'));if(!Array.isArray(d))throw Error('The ticker list was empty');loaded=d.filter(x=>x.contract_type==='perpetual_futures'&&/USD$/.test(x.symbol)).map(x=>({symbol:x.symbol,base:x.symbol.replace(/USD$/,''),quote:'USD',price:+x.close,volume:+x.turnover_usd,change:+x.ltp_change_24h,exchange:ex})).sort((a,b)=>(b.volume||0)-(a.volume||0))}else{let d=unwrap(await fetchJson('shark',`/v1/exchange/exchangeInfo?market=${q}`));let contracts=Array.isArray(d)?d:(d?.contracts??d?.market?.flatMap?.(m=>m.contracts??[])??d?.markets?.flatMap?.(m=>m.contracts??[])??[]);if(contracts.length&&contracts[0]?.contracts)contracts=contracts.flatMap(m=>m.contracts??[]);if(!contracts.length)throw Error('The contract list was empty');loaded=[...new Map(contracts.filter(c=>typeof(c.name??c.symbol)==='string'&&(c.name??c.symbol).endsWith(q)&&(c.contractType??'PERPETUAL')==='PERPETUAL').map(c=>{let symbol=c.name??c.symbol;return [symbol,{symbol,base:c.baseAsset??symbol.slice(0,-q.length),quote:q,price:null,volume:null,change:null,exchange:ex,rawContract:c}]})).values()].sort((a,b)=>a.symbol.localeCompare(b.symbol))}if(id!==loadId)return;listings=loaded;if(!listings.length)throw Error('No perpetual contracts returned');renderListings();syncChartCoins();syncTicketCoins();if(typeof syncCustomAlertCoins==='function')syncCustomAlertCoins();if(!chartData&&activeTab==='chart')openChart($('chartCoin').value,mode);loadAlertProfile();if($('autoScan').checked&&!$('runStrategy').disabled)runStrategy();$('updated').textContent='Listings updated '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});$('dataNote').textContent=ex==='delta'?'Delta India USD perpetuals. Price and turnover from its ticker feed.':`Shark ${q} perpetuals. Prices and turnover load when you run the strategy scan.`}catch(e){if(id!==loadId)return;setError(`${e.message} Check your connection or tap Refresh.`);$('listingStatus').textContent='Listings unavailable';$('listingRows').innerHTML='<tr><td colspan="4" class="empty"><strong>Listings could not load.</strong>Refresh to retry.</td></tr>';$('updated').textContent='Feed unavailable'}}
async function fillSharkTickers(id){let pool=listings.slice(),next=0,done=0;async function worker(){while(next<pool.length&&id===scanId){let t=pool[next++];try{let d=unwrap(await fetchJson('shark',`/v1/market/ticker24Hr/${encodeURIComponent(t.symbol)}`));if(d&&+d.c>0){t.price=+d.c;t.volume=+d.q;t.change=+d.P}}catch(e){}if(id!==scanId)return;done++;$('updated').textContent=`Loading turnover ${done}/${pool.length}`}}await Promise.all(Array.from({length:8},worker));if(id===scanId)renderListings()}
async function dailyContext(t){try{return {bars:await candles(t.exchange,t.symbol,'1d',997),error:null}}catch(e){return {bars:[],error:e.message}}}
async function scanPair(t){let loaded=await Promise.allSettled([candles(t.exchange,t.symbol,'1h',75),candles(t.exchange,t.symbol,'4h',330)]),bars=loaded.map(x=>x.status==='fulfilled'?x.value:[]),issues=loaded.map((x,i)=>x.status==='rejected'?{symbol:t.symbol,reason:['1H','4H'][i]+': '+x.reason.message}:null).filter(Boolean);if(bars[0].length<30&&bars[1].length<30)throw Error(issues.map(x=>x.reason).join('; ')||'Insufficient history for this contract');let daily=[],dailyError=null,dailySkipped=!StrategySignals.needsDaily(...bars);if(!dailySkipped){try{daily=await candles(t.exchange,t.symbol,'1d',997)}catch(e){dailyError=e.message;issues.push({symbol:t.symbol,reason:'Daily: '+e.message})}}let evaluated=StrategySignals.scanAvailable(...bars,daily);return {...t,price:t.price??bars[0].at(-1)?.close,...evaluated.signals,plans:evaluated.plans,scanIssues:issues,dailyError,dailySkipped,h:bars[0],f:bars[1],sweeps:[...StrategySignals.sweeps(bars[0],3600000).map(x=>({...x,tf:"1H"})),...StrategySignals.sweeps(bars[1],14400000).map(x=>({...x,tf:"4H"}))],quality:{}}}
async function verifySetup(t){let matched=['scalp','breakout','ema','cross'].filter(m=>t[m]?.match);if(!matched.length)return t;let snapshot={},rules=null,five=[];try{five=await candles(t.exchange,t.symbol,'5m',90)}catch(e){t.verificationError=e.message}if(!matched.some(m=>t.plans?.[m])){for(let m of matched)t.quality[m]=StrategySignals.assess(t[m],null,snapshot,null,Date.now(),m);return t}try{let d=unwrap(await fetchJson(t.exchange,t.exchange==='delta'?'/v2/tickers/'+t.symbol:'/v1/market/ticker24Hr/'+t.symbol));snapshot={price:+(t.exchange==='delta'?d.close:d.c),at:tickerSourceTime(d,t.exchange),bid:+d.quotes?.best_bid,ask:+d.quotes?.best_ask};if(t.exchange==='shark'){let depth=unwrap(await fetchJson('shark','/v1/market/depth/'+t.symbol));snapshot.bid=+depth.b?.[0]?.[0];snapshot.ask=+depth.a?.[0]?.[0];}rules=await loadContract(t);if(snapshot.price>0)t.price=snapshot.price;}catch(e){t.verificationError=e.message}for(let m of matched){let p=t.plans[m];if(p&&rules){p={...p};for(let k of ['entry','stop','target'])p[k]=CustomerFlow.roundPrice(p[k],rules.tick);p.risk=p.side*(p.entry-p.stop);t.plans[m]=p;}let signalAt=m==='ema'?t.h?.at(-1)?.time+3600000:t[m].time+SEC[t[m].tf]*1000;snapshot.guard=StrategySignals.breakoutGuard(p,signalAt,five,m==='cross'?t.f:t.h,Date.now(),rules?.tick??0);t.quality[m]=StrategySignals.assess(t[m],p,snapshot,rules,Date.now(),m);t.quality[m].guard=snapshot.guard;if(t.verificationError)t.quality[m].reason=t.verificationError+' · '+t.quality[m].reason;}return t;}
const descriptions={scalp:'<strong>1 · 1H High-volume Breakout</strong>A completed 1H candle breaks its previous 20-bar range with at least 2× average volume. Both upward and downward breaks qualify. Strong closes only; moves more than 1% beyond the level are excluded.',breakout:'<strong>2 · Multi-timeframe / ATH Watch</strong>Aligns 1H, 4H, daily, weekly and monthly highs. Price must be within 2% of the loaded historical high, with 2× 1H and 1.5× 4H volume. A completed 1H close above every level and a 4H close above its range confirms the breakout. Up to 1,000 daily candles are checked; the displayed history high is not a verified lifetime ATH. Coins with insufficient history cannot qualify.',ema:'<strong>3 · 4H 200 EMA Consolidation</strong>Finds a 12-candle range no wider than 5%, close to the 200 EMA. Range-top setups watch for a breakout; range-bottom setups watch for a breakdown. A completed 1H close outside the range confirms the entry.',cross:'<strong>4 · Golden Cross / Death Cross</strong>A new 50 SMA / 200 SMA cross on a completed 4H candle, with at least 1.2× normal volume. Golden cross watches long entries; death cross watches short entries. Entry plans expire one hour after confirmation.'};
