function renderStrategy(){renderSweepChecks();let shown=results.filter(r=>(+$('minVolume').value===0||r.volume>=+$('minVolume').value)&&r[mode].match).sort((a,b)=>Number(!!b.quality?.[mode]?.recommended)-Number(!!a.quality?.[mode]?.recommended)||b.volume-a.volume);$('count').textContent=results.length;$('near').textContent=shown.length;$('breakouts').textContent=shown.filter(r=>r.scalp.match).length;$('highest').textContent=shown.length?compact(Math.max(...shown.map(r=>r.volume))):'—';$('quoteLabel').textContent=quote+' turnover';$('rows').innerHTML=shown.length?shown.map(r=>{let x=r[mode],state=setupState(r,mode);return `<tr data-symbol="${esc(r.symbol)}" tabindex="0" aria-expanded="${expanded===r.symbol}"><td class="coin">${esc(r.base)}<small>${esc(r.symbol)}</small></td><td><span class="pill ${state.kind}">${state.label} · ${x.label}</span><small>${esc(state.entryLabel)}</small></td><td>${money(x.level)}</td><td>${x.volume.toFixed(2)}×</td><td>${esc(x.why)}${marketNewsWatch||newsFlags.has(r.base.toUpperCase())?'<small class="risk-tag">Review news risk</small>':''}<button class="chart-link" data-chart="${esc(r.symbol)}">Chart &amp; plan</button><a class="chart-link" href="${esc(tradingViewUrl(r))}" target="_blank" rel="noopener noreferrer">Open TradingView</a><small class="muted">Details ↓</small></td></tr>${expanded===r.symbol?`<tr class="details"><td colspan="5"><div class="detail-grid"><div class="detail-card"><b>Strategy rules</b>${x.checks.map(c=>`<span>✓ ${esc(c.name)}</span>`).join('')}</div><div class="detail-card"><b>Price context</b><span>Latest ticker: ${money(r.price)}</span><span>24h turnover: ${compact(r.volume)}</span>${mode==='ema'?`<span>Range bottom: ${money(x.low)}</span><span>Range top: ${money(x.high)}</span><span>4h close to EMA: ${pct(x.distance)}</span>`:''}<span>Signal candle closed: ${new Date(x.time+SEC[x.tf]*1000).toLocaleString()}</span></div><div class="detail-card"><b>Entry quality checks</b>${(r.quality?.[mode]?.checks??[]).map(c=>`<span>${c.ok?'✓':'✕'} ${esc(c.name)}</span>`).join('')}<span>Rechecked during this scan. News and execution remain unverified. No win probability is implied.</span></div></div></td></tr>`:''}`}).join(''):`<tr><td colspan="5" class="empty"><strong>${results.length?'No coins match all rules.':'Choose a scan, then tap Scan market.'}</strong>${results.length?'No forced signals. Try again after the next candle closes.':'One scan checks all four strategies.'}</td></tr>`}
async function runStrategy(){let id=++scanId,ex=exchange();if(!listings.length){setError('Load the listings first, then run the scan.');return}clearError();renderScanIssues([]);results=[];expanded=null;renderStrategy();$('runStrategy').disabled=true;$('runStrategy').textContent='Scanning…';$('progress').classList.remove('hide');$('progressBar').style.width='2%';$('rows').innerHTML='<tr><td colspan="8" class="empty">Calculating closed-candle signals…</td></tr>';try{if(ex==='shark')await fillSharkTickers(id);else{let fresh=unwrap(await fetchJson('delta','/v2/tickers?contract_types=perpetual_futures'));if(id!==scanId)return;if(!Array.isArray(fresh))throw Error('Liquidity feed unavailable');let bySymbol=new Map(fresh.map(x=>[x.symbol,x]));for(let t of listings){let x=bySymbol.get(t.symbol);t.volume=x?+x.turnover_usd:0;if(x)t.price=+x.close}}if(id!==scanId)return;let candidates=listings.filter(x=>+$('minVolume').value===0||x.volume>=+$('minVolume').value).sort((a,b)=>b.volume-a.volume);if(!candidates.length)throw Error('No contracts meet this turnover filter. Try a lower minimum.');let next=0,done=0,out=[],issues=[];async function worker(){while(next<candidates.length&&id===scanId){let t=candidates[next++];try{let row=await scanWithRetry(t);if(id!==scanId)return;out.push(row);issues.push(...(row.scanIssues??[]));results=out.slice();if(done%4===0)renderStrategy()}catch(e){issues.push({symbol:t.symbol,reason:e.message??String(e)})}if(id!==scanId)return;done++;$('progressBar').style.width=Math.round(done/candidates.length*100)+'%';$('updated').textContent=`Scanning ${done}/${candidates.length}`}}await Promise.all(Array.from({length:ex==='shark'?1:4},worker));if(id!==scanId)return;renderScanIssues(issues);if(!out.length)throw Error('No contracts could be checked. Open scan details below for the affected coins and reasons.');$('updated').textContent='Checking live entry quality…';let matched=out.filter(t=>['scalp','breakout','ema','cross'].some(m=>t[m]?.match));for(let t of matched){if(id!==scanId)return;await verifySetup(t);if(id!==scanId)return;results=out.slice();renderStrategy();$('updated').textContent='Entry checks '+(matched.indexOf(t)+1)+'/'+matched.length}if(id!==scanId)return;results=out;expanded=null;renderStrategy();for(let t of out)for(let m of ['breakout','ema','scalp','cross']){let z=t[m];if(z?.match&&t.quality?.[m]?.recommended&&Date.now()-(z.time+SEC[z.tf]*1000)<SEC[z.tf]*1000)await alertSetup(t,m);}coverage=`Checked ${out.length}/${candidates.length} eligible contracts from ${listings.length} listings. ${out.filter(t=>t.dailyError).length} lack daily context for MTF. ${new Set(issues.map(x=>x.symbol)).size} coins have missing or incomplete timeframes; see scan details below. ${out.filter(t=>t.dailySkipped).length} failed necessary MTF checks before daily loading. Closed candles only. Refresh by scanning again.`;$('coverage').textContent=coverage;$('updated').textContent='Scan updated '+new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});}catch(e){if(id===scanId){setError(e.message);$('rows').innerHTML='<tr><td colspan="8" class="empty">Strategy data unavailable. Try again.</td></tr>'}}finally{if(id===scanId){$('progress').classList.add('hide');$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market'}}}
function tab(name){activeTab=name;for(let key of ['listings','strategy','chart','api','settings']){$(key+'View').classList.toggle('hide',key!==name);let b=document.querySelector(`[data-tab="${key}"]`);b.classList.toggle('active',key===name);if(key===name)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current')}if(typeof demoModeLayout==='function')demoModeLayout()}
