async function testHistory(){if(!chartData)return;let id=++historyId,base=chartData,m=base.mode,cost=+$('costPercent').value;let settings={daily:base.d,balance:+$('balance').value,risk:+$('riskPercent').value,leverage:+$('leverage').value,rules:base.rules};if(!(settings.balance>0)||!settings.rules){$('historyResult').textContent='Enter your balance and load exchange leverage limits first.';return}if(!Number.isFinite(cost)||cost<0||cost>5||$('costPercent').value===''){$('historyResult').textContent='Enter costs between 0% and 5% first.';return}$('testHistory').disabled=true;$('testHistory').textContent='Testing…';$('historyResult').textContent='Loading past candles and replaying the rules…';try{if(!base.historyBars){let [h,f]=await Promise.all([candles(base.t.exchange,base.t.symbol,'1h',997),candles(base.t.exchange,base.t.symbol,'4h',997)]);if(id!==historyId||chartData!==base)return;base.historyBars={h,f}}let {h,f}=base.historyBars,result=StrategySignals.backtest(h,f,m,cost,settings);if(id!==historyId||chartData!==base)return;let span=result.from&&result.to?`${new Date(result.from).toLocaleDateString()}–${new Date(result.to).toLocaleDateString()}`:'Not enough overlapping history',headline=result.n>=30?`${(result.rate*100).toFixed(0)}% historical wins`:'Not enough data for a probability';$('historyResult').innerHTML=`<div class="${result.n>=30?'history-rate':''}"><strong>${headline}</strong></div><p><strong>${settings.leverage}× simulation · Net P&amp;L ${money(result.pnl,base.t.quote)}</strong><br>Ending balance ${money(result.equity,base.t.quote)} · Max drawdown ${(result.maxDrawdown*100).toFixed(2)}% · ${result.liquidations} estimated liquidations.</p><p>${result.wins} wins / ${result.n} completed trades · ${result.losses} losses or flat results.</p>${result.n>=30?`<p>95% statistical interval: ${(result.interval[0]*100).toFixed(0)}–${(result.interval[1]*100).toFixed(0)}%. This is sampling uncertainty, not validated odds for the next trade.</p>`:'<p>At least 30 completed trades are needed to show a percentage.</p>'}<p>${result.n?`Average net result: ${result.meanR.toFixed(2)}R per trade. `:''}${cost.toFixed(2)}% estimated round-trip costs; funding excluded.</p><p class="small-note">${span}. ${h.length} 1h candles loaded. ${result.skipped} expired, incomplete, gapped or missing-history cases skipped. Patterns only; the current turnover filter and news are not replayed.</p>${result.n?`<details><summary>Recent test trades</summary><table><thead><tr><th>Entry date</th><th>Exit</th><th>Net R</th></tr></thead><tbody>${result.trades.slice(-8).reverse().map(t=>`<tr><td>${new Date(t.time).toLocaleDateString()}</td><td>${t.reason==='time'?'Time limit':t.reason==='stop'?'Stop':t.reason==='liquidation'?'Liquidation estimate':'Target'}</td><td>${t.net.toFixed(2)}R</td></tr>`).join('')}</tbody></table></details>`:''}`}catch(e){if(id===historyId)$('historyResult').textContent='Historical test unavailable: '+e.message}finally{if(id===historyId){$('testHistory').disabled=false;$('testHistory').textContent='Test historical win rate'}}}
$('listingRows').addEventListener('click',e=>{let b=e.target.closest('[data-chart]');if(b)openChart(b.dataset.chart)});$('loadChart').addEventListener('click',loadChart);$('chartCoin').addEventListener('change',loadChart);$('chartMode').addEventListener('change',()=>{historyId++;$('historyResult').textContent='Strategy changed. Run a new historical test.';$('testHistory').textContent='Test historical win rate';$('testHistory').disabled=!chartData?.rules;if(chartData){$('planMode').value='strategy';mountAdvancedChart(chartData.t);renderChart();startLive()}});$('chartZoom').addEventListener('change',renderChart);$('balance').addEventListener('input',renderRisk);$('riskPercent').addEventListener('change',renderRisk);$('costPercent').addEventListener('input',()=>{historyId++;renderRisk();$('historyResult').textContent='Costs changed. Run the test again.';$('testHistory').disabled=!chartData;$('testHistory').textContent='Test historical win rate'});$('testHistory').addEventListener('click',testHistory);


async function loadContract(t){try{let raw=t.exchange==='delta'?unwrap(await fetchJson('delta','/v2/products/'+encodeURIComponent(t.symbol))):t.rawContract;return StrategySignals.rules(raw,t.exchange)}catch(e){return null}}
function setLeverage(){let r=chartData?.rules;$('leverage').disabled=!r;$('leverage').innerHTML=r?r.choices.map(n=>`<option value="${n}">${n}×</option>`).join(''):'<option value="">Unavailable</option>';$('leverage').value=r?'1':'';$('leverageNote').textContent=r?`Current contract maximum: ${r.max}×. ${r.exchange==='delta'?'Base-tier notional cap: '+compact(r.maxNotional,chartData.t.quote)+'. ':''}Limits checked ${new Date().toLocaleTimeString()}.`:'Contract limits unavailable. Reload to retry.';if(r)$('costPercent').value=Math.max(.2,r.fee*2+.05).toFixed(2)}
function invalidateHistory(){historyId++;$('historyResult').textContent='Settings changed. Run the leveraged backtest again.';$('testHistory').textContent='Test leveraged backtest';$('testHistory').disabled=!chartData?.rules}
$('leverage').addEventListener('change',()=>{renderRisk();invalidateHistory()});$('balance').addEventListener('input',invalidateHistory);$('riskPercent').addEventListener('change',invalidateHistory);
let liveSockets=[],liveGeneration=0,receivedAt=0,lastSourceAt=0,liveSource='',fallbackBusy=false,closedBusy=false,alerts=[],seenAlerts=new Set(),tracked=[],notifyEnabled=window.Notification?.permission==='granted';
try{alerts=JSON.parse(localStorage.getItem('radarAlerts')||'[]').slice(0,30);seenAlerts=new Set(JSON.parse(localStorage.getItem('radarSeenAlerts')||'[]').slice(-300))}catch{}
