function saveTracked(){try{localStorage.setItem('radarTrackedEntries',JSON.stringify(tracked))}catch(e){}renderTracked()}
function renderAlerts(){$('alertRows').innerHTML=alerts.length?alerts.map(a=>`<div class="account-item">${a.meta&&!a.meta.custom?`<button class="chart-link" data-alert-coin="${esc(a.meta.symbol)}" data-alert-ex="${esc(a.meta.exchange)}" data-alert-mode="${esc(a.meta.mode)}" ${a.meta.surgeKey?`data-surge-key="${esc(a.meta.surgeKey)}"`:""}><strong>${esc(a.title)}</strong></button>`:`<b>${esc(a.title)}</b>`}</div>`).join(''):'No setup alerts yet. Start a scan below.';let badge=$('alertCount');if(badge)badge.textContent=alerts.length?String(alerts.length):''}
function alertUser(key,title,message,meta=null){if(seenAlerts.has(key))return;seenAlerts.add(key);alerts.unshift({title,message,time:Date.now(),meta});alerts=alerts.slice(0,30);try{localStorage.setItem('radarAlerts',JSON.stringify(alerts));localStorage.setItem('radarSeenAlerts',JSON.stringify([...seenAlerts].slice(-300)))}catch{}renderAlerts();if(typeof whatsappForward==='function')whatsappForward(key,title,message,meta);if(notifyEnabled&&window.Notification?.permission==='granted')try{new Notification(title,{tag:key})}catch{$('alertStatus').textContent='In-page alerts active; browser notification could not be delivered.'}}
async function alertSetup(t,m){if(!t.quality?.[m]?.recommended||Date.now()-t.quality[m].checkedAt>15000)return;let z=t[m],p=t.plans?.[m],key=`scan:${t.exchange}:${t.symbol}:${m}:${z.time}:${p?.confirmed?'confirmed':'forming'}`;if(seenAlerts.has(key))return;let q=t.quote,profile=readAlertProfile(t.exchange,q),message=p?`${p.confirmed?'Setup confirmed':'Forming setup — wait for a candle close beyond the trigger'}. Entry ${money(p.entry,q)}, stop ${money(p.stop,q)}, target ${money(p.target,q)}. `:'Watch the consolidation; there is no directional entry yet. ';if(p&&profile.balance>0){try{let rules=await loadContract(t),v=rules?StrategySignals.size(p,profile.balance,profile.risk,profile.cost,null,rules):null;message+=v&&!v.unsafe&&v.targetProfit>0?`Planned loss ${money(v.loss,q)} within ${profile.risk}% risk; size ${v.units.toPrecision(5)} ${t.base}; margin ${money(v.margin,q)} at ${v.leverage}×. Costs estimated at ${profile.cost}%; gaps can exceed this loss. `:'Size unavailable or risk limits not met — skip until reviewed. '}catch{message+='Contract limits unavailable — sizing not verified. '}}else message+='Set your balance below to receive a money-risk calculation. ';message+=marketNewsWatch||newsFlags.has(t.base)?'News risk flagged; review before entry.':'Check current price, spread and news before entry.';alertUser(key,`${t.symbol} · ${p?.confirmed?'Confirmed — review entry':'Forming — wait for close'} · ${z.label}`,message,{symbol:t.symbol,exchange:t.exchange,mode:m,confirmed:!!p?.confirmed,actionable:!!p,validUntil:z.time+(z.tf==='1h'?3600000:14400000)+(m==='cross'?3600000:z.tf==='1h'?3600000:14400000)})}

async function announceSetup(data){if(data.guardBusy)return;const key=data.mode+':'+Math.floor(Date.now()/10000);if(data.guardKey===key)return;data.guardBusy=true;try{let evaluated=StrategySignals.scanAvailable(data.h,data.f,data.d),row={...data.t,...evaluated.signals,plans:evaluated.plans,h:data.h,f:data.f,quality:{}};await verifySetup(row);if(chartData!==data)return;data.guardKey=key;data.quality=row.quality;renderChartGuard();let q=row.quality[data.mode];if(q?.recommended)await alertSetup(row,data.mode)}catch(e){if(chartData===data)$('chartGuardStatus').textContent='Entry checks unavailable: '+e.message}finally{data.guardBusy=false}}
function renderChartGuard(){let el=$('chartGuardStatus');if(!el||!chartData)return;const q=chartData.quality?.[chartData.mode];el.innerHTML='<strong>Fakeout filter &amp; separate liquidity sweep check</strong><p>'+esc(q?(q.recommended&&Date.now()-q.checkedAt<=15000?'Entry checks passed at '+new Date(q.checkedAt).toLocaleTimeString():q.recommended?'Entry checks stale — rechecking':q.reason):'Waiting for current entry checks')+'</p>';}

function renderTracked(){$('trackedRows').innerHTML=tracked.length?tracked.map((t,i)=>`<div class="account-item"><b>${esc(t.symbol)} · ${t.side===1?'Long':'Short'} · ${esc(t.mode)}</b><p>Entry ${money(t.entry,t.quote)} · Stop ${money(t.stop,t.quote)} · Target ${money(t.target,t.quote)}</p><p>${esc(t.status||'Waiting for live prices')} ${t.updated?' · '+new Date(t.updated).toLocaleTimeString():''}</p><button class="chart-link" data-remove-track="${i}">Stop tracking</button></div>`).join(''):'<p class="muted">Open a qualifying setup, enter your actual entry price and tap Track my entry. Tracking is manual; no exchange order is placed.</p>'}
function checkTracked(ex,symbol,price,at){for(let t of tracked.filter(t=>t.exchange===ex&&t.symbol===symbol)){if(at<(t.sourceAt??0))continue;t.sourceAt=at;t.updated=Date.now();let stop=t.side===1?price<=t.stop:price>=t.stop,target=t.side===1?price>=t.target:price<=t.target;let backInside=t.mode==='breakout'&&(t.side===1?price<t.trigger:price>t.trigger),expired=Date.now()-t.added>t.hold*3600000;t.status=stop?'STOP LEVEL REACHED':target?'TARGET REACHED':backInside?'At risk: price returned inside the breakout level':expired?'Review: strategy holding period expired':'Monitoring live price';if(stop||target||backInside||expired)alertUser(`risk:${t.id}:${stop?'stop':target?'target':backInside?'failed':'expired'}`,`${symbol}: ${t.status}`,`Latest ${money(price,t.quote)}. Entry ${money(t.entry,t.quote)}; stop ${money(t.stop,t.quote)}. Review your position.`)}renderTracked()}
function stopLive(){liveGeneration++;for(let s of liveSockets){try{s.disconnect?s.disconnect():s.close()}catch(e){}}liveSockets=[];receivedAt=0;liveSource='Connecting';if($('liveEntryState'))$('liveEntryState').textContent='Waiting for a fresh price update.';}
function applyPrice(ex,symbol,price,sourceTime,source){if(!(price>0&&Number.isFinite(price)))return;let ts=sourceTime;if(!(ts>0)||!Number.isFinite(ts)||Date.now()-ts>15000||ts>Date.now()+1000)return;checkTracked(ex,symbol,price,ts);if(chartData?.t.exchange!==ex||chartData.t.symbol!==symbol)return;if(ts<lastSourceAt)return;receivedAt=Date.now();lastSourceAt=ts;liveSource=source;$('livePrice').textContent=money(price,chartData.t.quote);chartData.lastPrice=price;if(source==='Streaming')paintTradeTick(price,ts);let p=chartData.plan;let state=!p?'No confirmed setup for the selected strategy.':p.side*(price-p.stop)<=0?'Stop level already breached — this entry plan is invalid.':p.side*(price-p.target)>=0?'Target already reached — wait for a new setup.':!p.confirmed?(p.side*(price-p.trigger)>=0?'Live trigger touched — await a completed 1h confirmation.':'Waiting for the entry trigger.'):`Live price is ${(Math.abs(price/p.entry-1)*100).toFixed(2)}% from the reference entry. Confirm your actual fill before sizing.`;$('liveEntryState').textContent=state;if(p&&!p.confirmed&&(p.side===1?price>=p.trigger:price<=p.trigger))alertUser(`trigger:${ex}:${symbol}:${chartData.mode}:${p.trigger}`,`${symbol}: live entry level touched`,'Provisional trigger. Wait for the required candle close; the setup can reverse.');}
function paintTradeTick(price,ts){
 if(!chartData||!tvCandles)return;
 const tf=chartData.mode==='scalp'?'1h':'4h',duration=SEC[tf]*1000,time=Math.floor(ts/duration)*duration;
 // Never invent the missing opening price or volume of an unseen candle.
 if(!tvLiveBar||tvLiveBar.time!==time)return;
 tvLiveBar={...tvLiveBar,high:Math.max(tvLiveBar.high,price),low:Math.min(tvLiveBar.low,price),close:price};
 tvCandles.update({time:time/1000,open:tvLiveBar.open,high:tvLiveBar.high,low:tvLiveBar.low,close:price});
}
function liveTimestamp(value){const n=Number(value);return Number.isFinite(n)&&n>0?(n>1e14?n/1000:n<1e11?n*1000:n):0;}
function applyCandle(ex,symbol,tf,c,ts){if(!['1h','4h'].includes(tf)||![c.open,c.high,c.low,c.close,c.time,c.volume].every(Number.isFinite)||!Number.isFinite(ts)||Date.now()-ts>15000||ts>Date.now()+1000||c.time>Date.now()||c.time%(SEC[tf]*1000)!==0||c.open<=0||c.low<=0||c.volume<0||c.high<Math.max(c.open,c.close)||c.low>Math.min(c.open,c.close))return;applyPrice(ex,symbol,c.close,ts,'Streaming');if(Date.now()-ts>15000)return;for(let t of tracked.filter(t=>t.exchange===ex&&t.symbol===symbol&&t.mode==='cross'&&tf==='4h')){let a=t.history??[];if(a.length&&c.time>a.at(-1).time){let last=a.at(-1);if(last.time+14400000<=Date.now()){let z=a.slice(-200);if(z.length===200){let fast=z.slice(-50).reduce((n,x)=>n+x.close,0)/50,slow=z.reduce((n,x)=>n+x.close,0)/200;if(t.side*(fast-slow)<0)alertUser('cross-invalid:'+t.id+':'+last.time,t.symbol+': crossover trend reversed','The 50/200 SMA trend is now against your tracked position.')}}a.push(c)}else if(a.length&&a.at(-1).time===c.time)a[a.length-1]=c;t.history=a.slice(-330)}if(chartData?.t.exchange!==ex||chartData.t.symbol!==symbol)return;chartData.candleTs??={};if(ts<(chartData.candleTs[tf]??0))return;chartData.candleTs[tf]=ts;let key=tf==='1h'?'allH':'allF',arr=chartData[key],prev=arr.at(-1),isNew=c.time>(prev?.time??-Infinity);if(c.time<(prev?.time??-Infinity))return;if(isNew)arr.push(c);else arr[arr.length-1]=c;chartData[key]=arr.slice(-1000);let viewTf=chartData.mode==='scalp'?'1h':'4h';if(viewTf===tf&&tvCandles&&ts>=lastSourceAt){tvCandles.update({time:c.time/1000,open:c.open,high:c.high,low:c.low,close:c.close});tvLiveBar=c;tvVolume?.update({time:c.time/1000,value:c.volume,color:c.close>=c.open?'#23866b45':'#d05e6a45'})}if(isNew)refreshClosed();}
function startLive(){stopLive();lastSourceAt=0;let generation=liveGeneration,targets=[...tracked.map(t=>({exchange:t.exchange,symbol:t.symbol})),...(chartData?[chartData.t]:[])];for(let ex of ['delta','shark']){let symbols=[...new Set(targets.filter(t=>t.exchange===ex).map(t=>t.symbol))];if(!symbols.length)continue;if(ex==='delta'){connectDeltaStream(symbols,generation);}else if(window.io){let s=window.io('https://fawss.sharkexchange.in/',{transports:['websocket'],reconnectionDelay:3000,reconnectionDelayMax:15000});liveSockets.push(s);s.on('connect',()=>s.emit('subscribe',{params:symbols.flatMap(symbol=>['kline_1h','kline_4h','aggTrade'].map(k=>symbol.toLowerCase()+'@'+k))}));s.on('kline',d=>{if(generation!==liveGeneration||!d.k)return;let k=d.k;applyCandle(ex,d.ps??d.s,k.i,{time:+k.t,open:+k.o,high:+k.h,low:+k.l,close:+k.c,volume:+k.v},+d.E)});s.on('aggTrade',d=>{if(generation===liveGeneration)applyPrice(ex,d.s,+d.p,+d.T||+d.E,'Streaming')})}}}
function connectDeltaStream(symbols,generation,attempt=0){
 if(generation!==liveGeneration)return;
 let ws,watchdog,heartbeatAt=Date.now(),opened=false;
 const retry=()=>{clearInterval(watchdog);if(generation!==liveGeneration)return;liveSource='Reconnecting';pollFallback();const delay=Math.min(30000,1000*2**Math.min(attempt,5));setTimeout(()=>connectDeltaStream(symbols,generation,attempt+1),delay);};
 try{ws=new WebSocket('wss://public-socket.india.delta.exchange');}catch{retry();return;}
 liveSockets.push(ws);
 ws.onopen=()=>{if(generation!==liveGeneration){ws.close();return;}opened=true;heartbeatAt=Date.now();ws.send(JSON.stringify({type:'enable_heartbeat'}));ws.send(JSON.stringify({type:'subscribe',payload:{channels:[{name:'candlestick_1h',symbols},{name:'candlestick_4h',symbols},{name:'trades',symbols},{name:'ob_l2',symbols}]}}));};
 ws.onmessage=e=>{if(generation!==liveGeneration)return;try{const d=JSON.parse(e.data);if(d.type==='heartbeat'){heartbeatAt=Date.now();attempt=0;return;}if(!symbols.includes(d.sy))return;
 if(d.type==='trades'){applyPrice('delta',d.sy,+d.p,liveTimestamp(d.t??d.ts),'Streaming');}
 else if(d.type==='ob_l2'){renderStreamBook(d);}
 else if(d.type?.startsWith('candlestick_')){const tf=d.res,ts=liveTimestamp(d.ts);if(!SEC[tf])return;const time=d.cst?liveTimestamp(d.cst):Math.floor(ts/(SEC[tf]*1000))*SEC[tf]*1000;applyCandle('delta',d.sy,tf,{time,open:+d.o,high:+d.h,low:+d.l,close:+d.c,volume:+d.v},ts);}
 }catch{}};
 ws.onclose=()=>{liveSockets=liveSockets.filter(s=>s!==ws);retry();};
 watchdog=setInterval(()=>{if(generation!==liveGeneration){clearInterval(watchdog);return;}if(Date.now()-heartbeatAt>(opened?35000:15000)){clearInterval(watchdog);ws.close();}},1000);
}
function renderStreamBook(d){
 const t=chartData?.t,at=liveTimestamp(d.ts);if(!t||t.exchange!=='delta'||t.symbol!==d.sy||!at||Date.now()-at>15000||at>Date.now()+1000||!Array.isArray(d.a)||!Array.isArray(d.b))return;
 if(bookBest?.symbol===d.sy&&bookBest.at>at)return;
 const clean=a=>a.map(x=>({price:+x[0],size:+x[1]})).filter(x=>Number.isFinite(x.price)&&x.price>0&&Number.isFinite(x.size)&&x.size>=0);
 const asks=clean(d.a).sort((a,b)=>a.price-b.price).slice(0,8),bids=clean(d.b).sort((a,b)=>b.price-a.price).slice(0,8);if(!asks.length||!bids.length||asks[0].price<bids[0].price)return;
 bookBest={bid:bids[0].price,ask:asks[0].price,symbol:d.sy,exchange:'delta',at,stream:true};
 const rows=(a,cls)=>a.map(o=>`<div class="book-row ${cls}"><button type="button" data-book-price="${o.price}">${money(o.price,t.quote)}</button><span>${o.size.toLocaleString('en-US',{maximumFractionDigits:4})}</span></div>`).join('');
 $('bookAsks').innerHTML=rows(asks.slice().reverse(),'ask');$('bookBids').innerHTML=rows(bids,'bid');$('bookMid').textContent='Spread '+money(asks[0].price-bids[0].price,t.quote);$('bookStatus').textContent=d.sy+' · exchange stream · '+new Date(at).toLocaleTimeString();
}
