async function refreshClosed(){if(!chartData||closedBusy)return;closedBusy=true;let base=chartData;try{let [h,f,context]=await Promise.all([candles(base.t.exchange,base.t.symbol,'1h',150),candles(base.t.exchange,base.t.symbol,'4h',330),dailyContext(base.t)]);if(chartData!==base)return;let changed=h.at(-1).time!==base.h.at(-1).time||f.at(-1).time!==base.f.at(-1).time;base.h=h;base.f=f;base.d=context.bars;base.dailyError=context.error;base.allH=mergeClosedBars(h,base.allH,3600000);base.allF=mergeClosedBars(f,base.allF,14400000);if(changed){base.historyBars=null;invalidateHistory();renderChart();for(let t of tracked.filter(t=>t.symbol===base.t.symbol&&t.exchange===base.t.exchange&&t.mode==='cross')){let closes=f.map(c=>c.close),fast=closes.slice(-50).reduce((a,b)=>a+b)/50,slow=closes.slice(-200).reduce((a,b)=>a+b)/200;if(t.side*(fast-slow)<0)alertUser('cross-risk:'+t.id+':'+f.at(-1).time,t.symbol+': crossover invalidated','The 50/200 SMA trend has reversed against your tracked position.')}}}catch(e){$('chartStatus').textContent='Closed-candle refresh failed. Previous signal is not freshly verified.'}finally{closedBusy=false}}
