function prepareAccountPanel(name){let section=$(name+'Connection'),form=section.querySelector('.key-form'),note=form.nextElementSibling,status=$(name+'Status'),refresh=$('refresh'+name[0].toUpperCase()+name.slice(1)),positions=$(name+'Positions');let settings=document.createElement('details');settings.className='connection-settings';settings.id=name+'Settings';settings.open=true;let summary=document.createElement('summary');summary.textContent='Connection settings';settings.append(summary,form,note);let toolbar=document.createElement('div');toolbar.className='account-toolbar';let trade=document.createElement('button');trade.className='refresh';trade.type='button';trade.textContent='Take a trade';trade.addEventListener('click',async()=>{if(exchange()!==name){$('exchange').value=name;await loadListings()}tab('chart');setTicketMode(false);$('simpleTrade').scrollIntoView({block:'start',behavior:'smooth'})});toolbar.append(refresh,trade);section.insertBefore(status,section.querySelector('.connection-settings')??section.children[2]);section.insertBefore(toolbar,section.querySelector('details'));section.insertBefore(positions,section.querySelector('details'));section.append(settings)}
