function syncTicketCoins(){let old=$('ticketCoin').value,coins=listings;$('ticketCoin').innerHTML='<option value="">Choose a coin</option>'+coins.map(t=>`<option value="${esc(t.symbol)}">${esc(t.symbol)}</option>`).join('');if(coins.some(t=>t.symbol===old))$('ticketCoin').value=old;else if(coins.length){$('ticketCoin').value=coins.find(t=>t.symbol===$('chartCoin').value)?.symbol??coins[0].symbol;if(!customerInitializing)chooseTicketCoin();return}else{$('ticketEntry').value='';$('ticketStop').value='';$('ticketTarget').value='';ticketRules=null}refreshTicket()}
