function renderTradePositions(){if(!$('tradePositionsRows'))return;let ex=exchange(),account=ex==='delta'?deltaAccount:sharkAccount,connected=ex==='delta'?deltaConnected:sharkConnected,status=$('tradePositionsStatus');if(!connected){status.textContent='Connect your account in My trades to load wallet and positions.';$('tradePositionsRows').innerHTML='';return}if(!account||!Array.isArray(account.positions)){status.textContent='Positions unavailable. Refresh account or check the exchange.';$('tradePositionsRows').innerHTML='';return}let items=account.positions.filter(p=>ex==='delta'?+p.size!==0:p.positionStatus==='OPEN'&&+p.quantity!==0);status.textContent=items.length+' open · updated '+new Date(account.asOf).toLocaleTimeString()+(Date.now()-account.asOf>30000?' · stale, refresh account':'');if(!items.length){$('tradePositionsRows').innerHTML='<p class="ticket-note">No open positions on this account.</p>';return}let rows=items.map(p=>{let symbol=ex==='delta'?symbolOf(p):sharkCoin(p),q=ex==='delta'?'USD':p.quoteAsset??(symbol.endsWith('INR')?'INR':'USDT'),size=ex==='delta'?+p.size:+p.quantity,side=ex==='delta'?(size>0?'Long':'Short'):p.positionType,entry=ex==='delta'?p.entry_price:p.entryPrice,mark=ex==='delta'?p.mark_price:p.markPrice,margin=ex==='delta'?p.margin:p.margin??p.marginUsed,profit=ex==='delta'?p.unrealized_pnl:p.unrealisedPnl??p.unrealizedPnl,liq=ex==='delta'?p.liquidation_price:p.liquidationPrice,orders=(account.orders??[]).filter(o=>ex==='delta'?o.product_id===p.product_id&&o.side===(size>0?'sell':'buy'):sharkCoin(o)===symbol&&o.placeType==='POSITION'),stop=orders.find(o=>ex==='delta'?o.stop_order_type==='stop_loss_order'||+o.bracket_stop_loss_price>0:o.subType==='STOP_LOSS'),target=orders.find(o=>ex==='delta'?o.stop_order_type==='take_profit_order'||+o.bracket_take_profit_price>0:o.subType==='TAKE_PROFIT'),sl=ex==='delta'?stop?.stop_price??stop?.bracket_stop_loss_price:stop?.stopPrice??stop?.price,tp=ex==='delta'?target?.stop_price??target?.bracket_take_profit_price:target?.stopPrice??target?.price;return `<tr><td><button class="coin-link" data-trade-position="${esc(symbol)}">${esc(symbol)}</button></td><td>${esc(side)} · ${Math.abs(size).toLocaleString()}</td><td>${money(entry,q)}</td><td>${money(mark,q)}</td><td>${sl?money(sl,q):'<span class="negative">No stop shown</span>'} / ${tp?money(tp,q):'—'}</td><td>${money(liq,q)}</td><td>${money(margin,q)}</td><td class="${+profit>=0?'positive':'negative'}">${money(profit,q)}</td><td><button class="chart-link" data-manage-position="${esc(symbol)}">${ex==='delta'?'Set stop / target':'Manage'}</button></td></tr>`}).join('');$('tradePositionsRows').innerHTML=table(['Coin','Size','Entry','Mark','Stop / target','Liq. price','Margin','Unrealized P&L',''],[rows])}

// Existing positions are protected from the Trade screen, not by opening a new entry.
const protectionDialog=document.createElement('dialog');
protectionDialog.id='positionProtectionDialog';
protectionDialog.setAttribute('aria-label','Set position stop-loss and target');
protectionDialog.style.cssText='width:calc(100% - 32px);max-width:460px;padding:22px;border:1px solid #d2e2e8;border-radius:14px;box-shadow:0 18px 55px #0004;color:#18394b;background:white';
protectionDialog.innerHTML=`<h3 style="margin:0 0 10px">Set stop-loss &amp; target</h3>
<p id="positionProtectionHeading" role="status"></p>
<div class="control"><label for="positionProtectionStop">Stop-loss trigger price</label>
<input id="positionProtectionStop" type="number" min="0" step="any" inputmode="decimal"></div>
<div class="control"><label for="positionProtectionTarget">Take-profit trigger price</label>
<input id="positionProtectionTarget" type="number" min="0" step="any" inputmode="decimal"></div>
<p id="positionProtectionError" role="status" style="font-size:13px;line-height:1.5">After reviewing, a separate confirmation is required. Verify protection on Delta.</p>
<div style="display:flex;justify-content:flex-end;gap:12px;margin-top:16px">
<button class="mode" id="positionProtectionCancel" type="button">Cancel</button>
<button class="refresh" id="positionProtectionContinue" type="button">Review stop / target</button></div>`;
document.body.append(protectionDialog);
let protectingSymbol=null;
function showPositionProtection(symbol){
  if(!deltaConnected||!deltaWritable){$('ticketStatus').textContent='Enable reviewed Delta order actions in Settings first.';tab('settings');return}
  if(!deltaAccount||!Array.isArray(deltaAccount.positions)||!Array.isArray(deltaAccount.orders)||Date.now()-deltaAccount.asOf>30000){
    $('tradePositionsStatus').textContent='Position/order data is stale or unavailable. Refresh your Delta account, then try again.';return
  }
  const pos=deltaAccount.positions.find(p=>symbolOf(p)===symbol&&Number(p.size)!==0);
  if(!pos){$('tradePositionsStatus').textContent='Position changed. Refresh your Delta account.';return}
  protectingSymbol=symbol;
  const isLong=Number(pos.size)>0;
  $('positionProtectionHeading').textContent=symbol+' · '+(isLong?'Long':'Short')+
    ' · current mark '+money(pos.mark_price,'USD')+
    '. '+(isLong?'Stop below mark; target above.':'Stop above mark; target below.');
  $('positionProtectionStop').value='';
  $('positionProtectionTarget').value='';
  $('positionProtectionError').textContent='Uses a position bracket, closing the full position when triggered. Existing stops are not silently replaced.';
  protectionDialog.showModal();
}
$('positionProtectionCancel').addEventListener('click',()=>protectionDialog.close());
$('positionProtectionContinue').addEventListener('click',()=>{
  const stop=Number($('positionProtectionStop').value),target=Number($('positionProtectionTarget').value),symbol=protectingSymbol;
  const pos=deltaAccount?.positions?.find(p=>symbolOf(p)===symbol&&Number(p.size)!==0);
  const current=Number(pos?.mark_price)||Number(pos?.entry_price),side=Number(pos?.size)>0?1:-1;
  if(!(stop>0&&target>0&&current>0&&side*(current-stop)>0&&side*(target-current)>0)){
    $('positionProtectionError').textContent='Invalid prices. Long: stop < current < target. Short: target < current < stop.';return
  }
  protectionDialog.close();
  reviewAction({action:'protect',symbol,stop,target});
});

