function customerSyncDraft(){if(customerInitializing||!chartData||!customerDraft)return;let fields=customerDraftFields();if(customerDraft.exchange!==chartData.t.exchange||customerDraft.symbol!==chartData.t.symbol)return;if(['entry','stop','target','side'].some(k=>String(fields[k])!==String(customerDraft[k]))){customerDraft=CustomerFlow.edit(customerDraft,fields);customerPaintDraft()}customerUpdateStatus()}
function customerFillTicket(){customerInitializing=true;for(let [field,id] of [['entry','ticketEntry'],['stop','ticketStop'],['target','ticketTarget']])$(id).value=customerDraft?.[field]??'';$('ticketSide').value=customerDraft?.side===-1?'sell':'buy';$('ticketLong').classList.toggle('active',customerDraft?.side!==-1);$('ticketShort').classList.toggle('short-active',customerDraft?.side===-1);$('ticketAction').classList.toggle('short',customerDraft?.side===-1);customerInitializing=false}
