function setupState(r,m,now=Date.now()){
 let p=r.plans?.[m],signal=r[m],q=r.quality?.[m];
 if((m==='cross'&&signal?.time+18000000<now)||(p&&Number.isFinite(q?.expires)&&now>q.expires))return {kind:'expired',label:'Expired',entryLabel:'Entry window closed',entryReady:false};
 let state=p?{kind:p.confirmed?'confirmed':'forming',label:p.confirmed?'Confirmed':'Forming'}:{kind:'watch',label:'Watch only'};
 state.entryReady=false;
 if(!p)state.entryLabel='Wait for a qualifying entry';
 else if(!q)state.entryLabel=r.quality?'Entry checks pending':'Entry checks not run';
 else if(!Number.isFinite(q.checkedAt)||now-q.checkedAt>60000)state.entryLabel='Recheck entry · checks are stale';
 else if(!p.confirmed)state.entryLabel='Wait for candle confirmation';
 else if(q.recommended){state.entryLabel='Entry checks passed · ready for review';state.entryReady=true}
 else state.entryLabel='Entry not recommended · '+(q.reason||'Checks incomplete');
 return state;
}

function mergeClosedBars(closed,shown=[],duration,now=Date.now()){let last=closed.at(-1)?.time??-Infinity;return [...closed,...shown.filter(c=>c.time>last&&c.time<=now)].slice(-1000)}
function customerReviewGate(context){if(context?.action!=='open')return null;if(context.ticket&&context.ticket!==reviewTicketSnapshot())return 'Amount, leverage or direction changed after review. Close and review the updated order.';if(!customerDraft||context.exchange!==customerDraft.exchange||context.symbol!==customerDraft.symbol||context.revision!==customerDraft.revision)return 'The plan changed after review. Close this review and review the current plan again.';return customerTradeGate()}

