// Requests are serialized; response revisions keep older snapshots from replacing newer state.
function demoAvailable(currency){if(!demoState)return 0;return Math.max(0,demoState.cash[currency]-demoState.positions.filter(p=>p.currency===currency).reduce((s,p)=>s+p.margin,0))}
async function demoFetch(body){let r=await fetch('/api/demo',{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(30000)});if(!r.headers.get('content-type')?.includes('application/json')||r.redirected)throw Error('Sign in again to load your saved demo account.');let d=await r.json();if(!r.ok){let e=Error(d.error||'Demo request failed');e.httpStatus=r.status;throw e}return d}
function demoAccept(d){if(d.state&&d.version>=demoVersion){demoState=d.state;demoVersion=d.version;demoError=(d.errors??[]).map(x=>x.symbol+': '+x.error).join(' ');demoLoaded=true;renderDemo();if(ticketDemo)refreshTicket()}return d}
function demoRequest(body){let run=demoQueue.then(async()=>{demoBusy=true;customerUpdateStatus();try{let d=await demoFetch(body);return demoAccept(d)}catch(e){demoError=e.message;renderDemo();throw e}finally{demoBusy=false;customerUpdateStatus();renderDemo()}});demoQueue=run.catch(()=>{});return run}
async function refreshDemo(){try{await demoRequest();if(pendingDemoOpen&&!demoState.requests?.includes(pendingDemoOpen.requestId)){try{await demoRequest({...pendingDemoOpen.payload,requestId:pendingDemoOpen.requestId})}catch(e){if(e.httpStatus&&e.httpStatus<500)pendingDemoOpen=null;throw e}}if(pendingDemoOpen&&demoState.requests?.includes(pendingDemoOpen.requestId)){customerOrderAccepted(pendingDemoOpen.context,true);pendingDemoOpen=null}await demoMark()}catch{}}
async function demoOpen(x){if(demoBusy||demoOpening)throw Error('Please wait for the current demo request.');let t={...chartData?.t};if(!t.symbol)throw Error('Choose a coin first');let payload={action:'open',strategy:customerDraft?.strategyContext??null,exchange:t.exchange,symbol:t.symbol,currency:t.quote,entry:x.p.entry,stop:x.p.stop,target:x.p.target,side:x.p.side,units:x.quantity,leverage:x.v.leverage},context={exchange:t.exchange,symbol:t.symbol,action:'open',revision:customerDraft?.revision};if(pendingDemoOpen&&JSON.stringify(pendingDemoOpen.payload)!==JSON.stringify(payload))throw Error('Resolve the previous demo request with Refresh demo account before changing this plan.');pendingDemoOpen??={payload,context,requestId:crypto.randomUUID()};demoOpening=true;customerUpdateStatus();try{await demoRequest({...payload,requestId:pendingDemoOpen.requestId});pendingDemoOpen=null}catch(e){if(e.httpStatus&&e.httpStatus<500)pendingDemoOpen=null;throw e}finally{demoOpening=false;customerUpdateStatus()}}
async function demoMark(){if(demoBusy||demoOpening||!demoState?.positions.length)return;try{await demoRequest({action:'sync'})}catch{}}
function demoModeLayout(){let monitor=$('tradeMonitorPanel');if(monitor){let target=activeTab==='api'?$('apiView'):tradeWorkspace;if(monitor.parentElement!==target)target.prepend(monitor)}for(let id of ['customerPractice','tradePractice'])if($(id))$(id).checked=ticketDemo;$('ticketConnect')?.classList.toggle('hide',ticketDemo);$('tradePositions')?.classList.toggle('hide',ticketDemo);for(let ex of ['delta','shark'])$(ex+'Connection')?.classList.toggle('hide',ticketDemo);let panel=$('demoPanel');if(panel){panel.classList.toggle('hide',!ticketDemo);let target=activeTab==='api'?$('apiView'):tradeWorkspace;if(panel.parentElement!==target)target.append(panel)}}
function seedDemoPlan(force=false){if(!chartData)return;let t=chartData.t;if(!force&&(customerDraft?.cleared||CustomerFlow.plan(customerDraft)))return;let entry=chartData.lastPrice??chartData.allH?.at(-1)?.close??t.price;if(!(entry>0))return;let side=$('ticketSide').value==='sell'?-1:1,tick=chartData.rules?.tick;customerDraft=CustomerFlow.edit(CustomerFlow.create(t.exchange,t.symbol,chartData.mode),{entry:CustomerFlow.roundPrice(entry,tick),stop:CustomerFlow.roundPrice(entry*(1-side*.01),tick),target:CustomerFlow.roundPrice(entry*(1+side*.02),tick),side});customerFillTicket();customerPaintDraft()}
async function demoUseLatest(){if(!chartData){$('ticketStatus').textContent='Choose a coin first.';return}let t={...chartData.t},revision=customerDraft?.revision;$('ticketBest').disabled=true;try{let d=await demoFetch({action:'quote',exchange:t.exchange,symbol:t.symbol});if(chartData?.t.exchange!==t.exchange||chartData?.t.symbol!==t.symbol||revision!==customerDraft?.revision)return;chartData.lastPrice=d.quote.price;seedDemoPlan(true);refreshTicket();$('ticketStatus').textContent='Demo prices updated from the exchange. Review the stop and target before submitting.'}catch(e){$('ticketStatus').textContent=e.message}finally{$('ticketBest').disabled=false}}
function renderDemo(){if(!$('demoRows'))return;demoModeLayout();let error=$('demoError');error.textContent=demoError;error.classList.toggle('hide',!demoError);if(!demoState){$('demoStatus').textContent='Demo account not loaded. Tap Refresh demo account to retry.';return}let c=chartData?.t.quote??market(),positions=demoState.positions.filter(p=>p.currency===c),unrealized=positions.reduce((s,p)=>s+p.side*p.units*(p.mark-p.entry)-p.units*p.mark*.001,0),realized=demoState.realized?.[c]??demoState.history.filter(p=>p.currency===c).reduce((s,p)=>s+p.pnl,0);$('demoStatus').textContent=(demoBusy?'Updating… · ':'')+demoState.positions.length+' demo positions · '+c+' account';$('demoBalance').textContent='Cash '+money(demoState.cash[c],c)+' · Available '+money(demoAvailable(c),c)+' · Estimated equity '+money(demoState.cash[c]+unrealized,c)+' · Realized P&L '+money(realized,c);$('demoRows').innerHTML=demoState.positions.length?table(['Coin','Side / units','Entry','Current price','Stop / target','Margin','Net P&L estimate','Action'],demoState.positions.map(p=>{let fresh=p.markAt&&Date.now()-p.markAt<=15000;return `<tr><td><button class="chart-link" data-demo-chart="${esc(p.id)}">${esc(p.symbol)}</button><small>${esc(p.exchange)}</small></td><td>${p.side===1?'Long':'Short'} · ${Number(p.units.toPrecision(6))} · ${p.leverage}×</td><td>${money(p.entry,p.currency)}</td><td>${money(p.mark,p.currency)}<small>${fresh?'Updated':'Stale'} ${p.markAt?esc(new Date(p.markAt).toLocaleTimeString()):''}</small></td><td>${money(p.stop,p.currency)} / ${money(p.target,p.currency)}</td><td>${money(p.margin,p.currency)}</td><td>${money(p.side*p.units*(p.mark-p.entry)-p.entryFee-p.units*p.mark*.001,p.currency)}</td><td><button class="chart-link" data-demo-close="${esc(p.id)}" ${demoBusy?'disabled':''}>Close demo</button></td></tr>`})):'<p>No open demo positions. Choose a coin, review the plan and select Simulate trade.</p>';$('demoHistory').innerHTML=demoState.history.length?table(['Coin','Entry / exit','Net P&L','Reason','Closed'],demoState.history.slice(0,20).map(p=>`<tr><td>${esc(p.symbol)} · ${esc(p.exchange)}</td><td>${money(p.entry,p.currency)} / ${money(p.exit,p.currency)}</td><td>${money(p.pnl,p.currency)}</td><td>${esc(p.reason)}</td><td>${esc(new Date(p.closedAt).toLocaleString())}</td></tr>`)):'<p>No closed demo trades yet.</p>'}
function mountDemo(){let box=document.createElement('section');box.className='panel trade-positions';box.id='demoPanel';box.innerHTML='<h3>Demo positions</h3><p id="demoStatus" role="status">Loading saved demo account…</p><p id="demoBalance"></p><p id="demoError" class="error hide" role="alert"></p><p class="ticket-note">Demo fills use your entered price; 0.1% fee per side. All open coins refresh automatically while the app is open. Closing fetches a fresh exchange price. Stop and target checks resume when reopened; missed prices while closed are not replayed.</p><button id="demoRefresh" class="refresh">Refresh demo account</button><div id="demoRows"></div><details open><summary>Closed demo trades</summary><div id="demoHistory"></div></details>';tradeWorkspace.append(box);let practice=$('customerPractice'),toggle=document.createElement('label');toggle.className='ticket-note demo-toggle';let check=document.createElement('input');check.type='checkbox';check.id='tradePractice';toggle.append(check,document.createTextNode(' Demo trading — simulated funds'));$('simpleTrade').prepend(toggle);check.addEventListener('change',()=>setTicketMode(check.checked));$('demoRefresh').addEventListener('click',refreshDemo);box.addEventListener('click',async e=>{let b=e.target.closest('[data-demo-close],[data-demo-chart]');if(!b||demoBusy)return;let p=demoState?.positions.find(x=>x.id===(b.dataset.demoClose??b.dataset.demoChart));if(!p)return;try{if(b.dataset.demoChart){if(exchange()!==p.exchange||market()!==p.currency){$('exchange').value=p.exchange;if(p.exchange==='shark')$('market').value=p.currency;await loadListings()}openChart(p.symbol,mode);return}await demoRequest({action:'close',id:p.id});$('ticketStatus').textContent='Demo position closed. See Closed demo trades.'}catch{}});demoModeLayout();refreshDemo();setInterval(()=>{if(!document.hidden)demoMark()},10000);window.addEventListener('online',refreshDemo);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshDemo()})}
mountDemo();

async function backgroundSettingsRequest(body){let r=await fetch('/api/background',{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(15000)});return accountResponse(r,'Background alerts')}
async function refreshBackground(){try{let d=await backgroundSettingsRequest();if(!backgroundFormLoaded){$('backgroundEnabled').checked=d.settings.enabled;$('backgroundWatchlist').value=d.settings.watchlist.map(x=>x.exchange+':'+x.symbol).join(', ');backgroundFormLoaded=true}let last=d.last;$('backgroundStatus').textContent=!d.settings.enabled?'Background scanning paused.':last?'Last scan '+new Date(last.completedAt).toLocaleString()+' · '+last.results.length+' setups · '+last.errors.length+' scan issues'+(Date.now()-last.completedAt>90*60000?' · overdue; monitoring needs attention':''):'No completed background scan recorded yet.';$('backgroundResults').innerHTML=last?table(['Coin','Setup','Entry / stop / target','Validity'],last.results.map(x=>`<tr><td>${esc(x.exchange+' '+x.symbol)}</td><td>${esc(x.mode)} · ${x.confirmed?'Confirmed':'Forming'}</td><td>${esc(x.entry)} / ${esc(x.stop)} / ${esc(x.target)}</td><td>${Date.now()>x.validUntil?'Expired':'Until '+esc(new Date(x.validUntil).toLocaleTimeString())}</td></tr>`))+last.errors.map(x=>`<p class="ticket-note">${esc(x.exchange+' '+x.symbol)}: ${esc(x.error)}</p>`).join('')+'<p class="ticket-note">'+esc(last.delivery)+' · '+esc(last.news)+'</p>':''}catch(e){$('backgroundStatus').textContent=e.message}}
var backgroundFormLoaded=false;
function mountBackground(){let box=document.createElement('section');box.className='panel planner-card';box.innerHTML='<h3>Background setup alerts</h3><p>The background schedule must be enabled for hourly scans while the app is closed. This watchlist is separate from the full-market scan. Up to eight coins; completed candles only. A missed or stale scan is shown here. WhatsApp uses your saved opt-in and provider settings below.</p><label><input id="backgroundEnabled" type="checkbox"> Enable background watchlist</label><label>Exchange and coin<input id="backgroundWatchlist" placeholder="delta:BTCUSD, delta:ETHUSD, shark:BTCUSDT"></label><button id="backgroundSave">Save background watchlist</button><button id="backgroundRefresh" class="refresh">Refresh scan status</button><p id="backgroundStatus" role="status">Loading background scan status…</p><div id="backgroundResults"></div>';$('customerSettings').insertBefore(box,$('customerSettings').firstChild);$('backgroundSave').addEventListener('click',async()=>{let b=$('backgroundSave');b.disabled=true;try{let watchlist=$('backgroundWatchlist').value.split(',').map(v=>{let [exchange,symbol]=v.trim().split(':');return {exchange:exchange?.toLowerCase(),symbol:symbol?.toUpperCase()}});await backgroundSettingsRequest({enabled:$('backgroundEnabled').checked,watchlist});await refreshBackground();$('backgroundStatus').textContent='Watchlist saved. The next scheduled scan uses these coins.'}catch(e){$('backgroundStatus').textContent=e.message}finally{b.disabled=false}});$('backgroundRefresh').addEventListener('click',refreshBackground);refreshBackground();setInterval(refreshBackground,60000)}
mountBackground();

function accountReady(a){return !!a&&Array.isArray(a.positions)&&Array.isArray(a.orders)&&Array.isArray(a.wallets)&&a.wallets.length>0&&!(a.errors??[]).some(e=>!/^(fills|trades):/.test(e));}

function reviewTicketSnapshot(){return JSON.stringify(['ticketCoin','ticketSide','ticketEntry','ticketStop','ticketTarget','ticketAmount','ticketLeverage'].map(id=>$(id)?.value));}

for(let [id,ex] of [['orderReview','delta'],['sharkReview','shark']])$(id).addEventListener('cancel',()=>{customerReviewContexts[ex]=null;if(ex==='delta')reviewId=null;else sharkReviewId=null});
function mountScanControls(){let cancel=document.createElement('button');cancel.type='button';cancel.className='refresh';cancel.id='cancelScan';cancel.textContent='Stop scan';cancel.addEventListener('click',()=>{scanId++;$('runStrategy').disabled=false;$('runStrategy').textContent='Scan market';$('progress').classList.add('hide');$('coverage').textContent='Scan stopped. Only completed checks are shown; remaining coins were not checked.';renderStrategy()});$('runStrategy').after(cancel);}
mountScanControls();

var tradeMonitorBusy=false,tradeMonitorState={tracks:[],events:[]};
async function tradeMonitorRequest(body){const r=await fetch('/api/trade-monitor',{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(90000)});return accountResponse(r,'Trade tracking')}
function renderTradeMonitor(){
 if(!$('tradeMonitorRows'))return;
 const active=tradeMonitorState.tracks.filter(t=>t.active);
 $('tradeMonitorRows').innerHTML=active.length?active.map(t=>`<article class="account-item"><button class="chart-link" data-monitor-chart="${esc(t.id)}">${esc(t.health?.title??t.symbol+' · Waiting for the first check')}</button><small>${t.checkedAt?'Checked '+new Date(t.checkedAt).toLocaleTimeString():'Pending check'}${t.checkedAt&&Date.now()-t.checkedAt>60000?' · STALE — check broker':''}</small><button class="chart-link" data-monitor-stop="${esc(t.id)}">Stop alerts</button></article>`).join(''):'<p>No strategy trades are being tracked. New strategy trades link automatically. For an existing trade, open its strategy chart and choose Track open position.</p>';
 $('tradeMonitorHistory').innerHTML=tradeMonitorState.events.length?tradeMonitorState.events.slice(0,20).map(e=>`<div class="account-item"><b>${esc(e.title)}</b></div>`).join(''):'No trade alerts yet.';
}
async function refreshTradeMonitor(check=false){
 if(tradeMonitorBusy)return;tradeMonitorBusy=true;
 try{const d=await tradeMonitorRequest(check?{action:'check'}:undefined);tradeMonitorState={...d,tracks:d.tracks??[],events:d.events??[]};renderTradeMonitor();$('tradeMonitorStatus').textContent=(d.busy?'A trade check is already running.':check?'Trade checks updated.':'Saved strategy trades loaded.')+(location.hostname==='localhost'?' Checks continue every 20 seconds while the local server is running.':' Checks run every 20 seconds while this page is open; sleeping tabs can delay them. Closed-app checks require an enabled background schedule and run only hourly.');if(d.delivery)$('tradeMonitorDelivery').textContent=d.delivery;
 for(const e of tradeMonitorState.events.filter(e=>Date.now()-e.at<120000).reverse())alertUser('monitor:'+e.id,e.title,'',{monitor:true,symbol:e.symbol,exchange:e.exchange,mode:e.mode});
 }catch(e){if($('tradeMonitorStatus'))$('tradeMonitorStatus').textContent='Tracking unavailable — check your broker. '+e.message}finally{tradeMonitorBusy=false;renderTradeMonitor()}
}
async function linkOpenStrategy(){const p=chartData?.plan,t=chartData?.t;if(!p||!t||p.manual){$('trackStatus').textContent='Choose a strategy plan before linking your open position.';return}const signal=StrategySignals.scanAvailable(chartData.h,chartData.f,chartData.d).signals[chartData.mode];const strategy={mode:chartData.mode,level:chartData.mode==='ema'?p.trigger:signal.level,signalAt:signal.time+SEC[signal.tf]*1000};$('trackSetup').disabled=true;try{await tradeMonitorRequest({action:'link',exchange:t.exchange,symbol:t.symbol,demo:ticketDemo,side:p.side,stop:p.stop,target:p.target,strategy});$('trackStatus').textContent='Open position linked. Strategy alerts are in Active trade tracking.';await refreshTradeMonitor(true)}catch(e){$('trackStatus').textContent=e.message}finally{$('trackSetup').disabled=false}}
function mountTradeMonitor(){const box=document.createElement('section');box.id='tradeMonitorPanel';box.className='panel trade-positions';box.innerHTML='<h3>Active trade tracking</h3><p id="tradeMonitorStatus" role="status">Loading saved strategy trades…</p><button id="tradeMonitorRefresh" class="refresh">Check trades now</button><div id="tradeMonitorRows"></div><details><summary>Trade alert history</summary><div id="tradeMonitorHistory"></div></details><p id="tradeMonitorDelivery" class="small-note"></p><details><summary>What the alerts check</summary><p>Stop and target, liquidation distance where available, stop coverage, the original breakout level or 50/200 SMA trend, closed 5m failed breaks, separate liquidity-sweep patterns, a loss of half the initial price risk, and profit protection after 1R. R is the original entry-to-stop price distance. These are review prompts; no position, stop or leverage is changed automatically. Reducing position size can reduce exposure; withdrawing margin is not a risk-reduction action. Strategy holding describes the latest checks, not a guaranteed outcome.</p></details>';tradeWorkspace.append(box);$('tradeMonitorRefresh').addEventListener('click',()=>refreshTradeMonitor(true));box.addEventListener('click',async e=>{const b=e.target.closest('[data-monitor-stop],[data-monitor-chart]');if(!b)return;const t=tradeMonitorState.tracks.find(t=>t.id===(b.dataset.monitorStop??b.dataset.monitorChart));if(!t)return;if(b.dataset.monitorStop){try{await tradeMonitorRequest({action:'stop',id:t.id});await refreshTradeMonitor()}catch(e){$('tradeMonitorStatus').textContent=e.message}return}if(exchange()!==t.exchange||market()!==(t.symbol.endsWith('USDT')?'USDT':t.symbol.endsWith('INR')?'INR':'USD')){$('exchange').value=t.exchange;if(t.exchange==='shark')$('market').value=t.symbol.endsWith('INR')?'INR':'USDT';await loadListings()}openChart(t.symbol,t.strategy.mode);});refreshTradeMonitor(true);setInterval(()=>{renderTradeMonitor();if(!document.hidden)refreshTradeMonitor(true)},20000);window.addEventListener('online',()=>refreshTradeMonitor(true));document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshTradeMonitor(true)});}
mountTradeMonitor();

var surgeState={job:null,settings:{enabled:false},alerts:[]},surgeBusy=false,surgeGeneration=0;
async function surgeRequest(body){const r=await fetch('/api/surge',{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(90000)});return accountResponse(r,'Volume surge scanner')}
function renderSurge(){if(!$('surgeStatus'))return;const j=surgeState.job;$('surgeStart').disabled=surgeBusy;$('surgePause').disabled=!surgeState.settings?.enabled;$('surgeStart').textContent=surgeBusy?'Checking coins…':'Start / refresh volume alerts';
 $('surgeStatus').textContent=!j?'Start to rank the selected market and scan its top 20 coins.':`${j.exchange==='delta'?'Delta India':'Shark'} · ${j.quote} · `+(j.phase==='rank'?`Ranking turnover ${j.cursor}/${j.total}`:j.phase==='scan'?`Checking ${j.cursor}/${j.top.length} coins`:j.phase==='failed'?j.error:`Checked ${j.rows.length}/${j.top.length} · ${new Date(j.completedAt).toLocaleTimeString()}`)+(surgeState.settings?.enabled?' · Auto checks enabled while open':' · Alerts paused');
 $('surgeAlertTitles').innerHTML=(surgeState.alerts??[]).slice(0,12).map(a=>`<button class="surge-alert" data-surge-alert="${esc(a.key)}"><strong>${esc(a.title)}</strong></button>`).join('')||'<p>No final confirmation alerts yet.</p>';
 $('surgeRows').innerHTML=j?.rows?.length?table(['Rank / coin','24h traded value','5m','15m','30m','1h','Liquidity sweep','Fakeout filter','Result'],[...j.rows].sort((a,b)=>Number(b.confirmed&&b.valid)-Number(a.confirmed&&a.valid)||a.rank-b.rank).map(r=>`<tr><td><b>#${r.rank} ${esc(r.symbol)}</b></td><td>${compact(r.turnover,j.quote)}</td>${['5m','15m','30m','1h'].map(tf=>{let c=r.checks?.find(c=>c.tf===tf);return `<td><span class="pill ${c?.ok?'confirmed':'forming'}">${c?.ok?'Pass':c?.available?'Waiting':'Unavailable'}</span><small>${c?.ratio!==undefined?c.ratio.toFixed(1)+'× volume':''}</small></td>`}).join('')}<td>${esc(r.sweeps?.map(s=>s.tf+' '+s.label).join(', ')||'None detected')}</td><td>${esc(r.guard?(r.guard.passed?'Passed':r.guard.reason):'Awaiting hourly alignment')}</td><td><strong>${esc(r.error??(r.confirmed?(r.valid?'1H CONFIRMED · '+(r.side===1?'LONG':'SHORT'):r.reason):r.watch?'Early watch · no alert':'No alignment'))}</strong>${r.confirmed?`<button class="chart-link" data-surge-coin="${esc(r.symbol)}">Chart &amp; plan</button>`:''}</td></tr>`)):'<p>The ranked coins and four confirmation checks will appear here.</p>';
 $('surgeDelivery').textContent=j?.delivery??'';
}
function acceptSurge(d){surgeState=d;renderSurge();for(const a of (d.alerts??[]).filter(a=>Date.now()-a.at<120000).reverse())alertUser(a.key,a.title,'',{monitor:true,surge:true,surgeKey:a.key,exchange:a.exchange,symbol:a.symbol,mode:'scalp'});}
async function runSurge(auto=false){if(surgeBusy)return;surgeState.failed=false;let generation=++surgeGeneration;surgeBusy=true;renderSurge();try{const s=auto?surgeState.settings:{exchange:exchange(),quote:market()};let d=await surgeRequest({action:'start',exchange:s.exchange,quote:s.quote});if(generation!==surgeGeneration)return;acceptSurge(d);while(d.settings.enabled&&['rank','scan'].includes(d.job?.phase)&&generation===surgeGeneration){if(d.busy)break;d=await surgeRequest({action:'step',id:d.job.id});if(generation!==surgeGeneration)return;acceptSurge(d)}}catch(e){$('surgeStatus').textContent=e.message;surgeState.failed=true;}finally{surgeBusy=false;$('surgeStart').disabled=false;$('surgeStart').textContent='Start / refresh volume alerts';}}
async function openSurgePlan(a){if(!a?.plan)return;const p=a.plan;if(exchange()!==a.exchange||market()!==a.quote){$('exchange').value=a.exchange;if(a.exchange==='shark')$('market').value=a.quote;await loadListings()}$('chartCoin').value=a.symbol;$('chartMode').value='scalp';$('planMode').value='strategy';tab('chart');await loadChart();if(chartData?.t.symbol!==a.symbol||chartData.t.exchange!==a.exchange)return;customerDraft=CustomerFlow.strategy(CustomerFlow.create(a.exchange,a.symbol,'scalp'),{...p,confirmed:true,trigger:p.level},p.closedAt,p.closedAt+3600000,chartData.rules?.tick);customerDraft.strategyContext={mode:'surge',level:p.level,signalAt:p.closedAt};customerDraft.surge=true;refreshSurgeGuard();customerFillTicket();customerPaintDraft();refreshTicket();$('ticketStatus').textContent='Volume surge: all four candle closes confirmed. Review current price, stop and position size.';}
function mountSurge(){const panel=document.createElement('section');panel.id='surgePanel';panel.className='panel planner-card';panel.innerHTML='<h2>5 · Top 20 volume surge</h2><p>5m → 15m → 30m → 1h. Final alerts require the hourly close plus 10 minutes of closed-candle follow-through.</p><div class="controls"><button class="refresh" id="surgeStart">Start / refresh volume alerts</button><button class="mode" id="surgePause">Pause volume alerts</button></div><p id="surgeStatus" role="status"></p><div id="surgeAlertTitles" aria-live="polite"></div><div id="surgeRows"></div><p id="surgeDelivery" class="small-note"></p><details><summary>Scanner rules &amp; timing</summary><p>Ranks the selected exchange and quote currency by 24-hour traded value, a liquidity proxy. Only the top 20 are checked. A missing turnover feed blocks ranking; missing candles block that coin. Each timeframe must close beyond its prior 20-candle range in the same direction, near the outer quarter of the candle. Volume must be at least 1.5× its previous 20-candle average on 5m, 15m and 30m, and 2× on 1h. All final checks use candles ending at the same exchange hourly close. Early checks can change and send no alerts.</p><p>Checks resume automatically after you start them. Results refresh with new 5-minute candles while this page is open; the final alert waits for the 1-hour close, not one hour after pressing Start. Final alerts also require two closed 5m candles after the hour, a passed fakeout filter, a separate opposing-sweep check, and a fresh live price still outside the breakout level. They identify a confirmed pattern, not a guaranteed large move. Background alerts require the existing schedule to be enabled and may be delayed. WhatsApp requires your saved consent and approved title-only template.</p></details>';$('alertCenter').after(panel);$('surgeStart').addEventListener('click',()=>runSurge());$('surgePause').addEventListener('click',async()=>{surgeGeneration++;try{acceptSurge(await surgeRequest({action:'pause'}))}catch(e){$('surgeStatus').textContent=e.message}});panel.addEventListener('click',e=>{const b=e.target.closest('[data-surge-alert],[data-surge-coin]');if(!b)return;const a=b.dataset.surgeAlert?surgeState.alerts.find(a=>a.key===b.dataset.surgeAlert):{exchange:surgeState.job.exchange,quote:surgeState.job.quote,symbol:b.dataset.surgeCoin,plan:surgeState.job.rows.find(r=>r.symbol===b.dataset.surgeCoin)};openSurgePlan(a).catch(e=>{$('surgeStatus').textContent=e.message})});surgeRequest().then(d=>{acceptSurge(d);if(d.settings.enabled)runSurge(true)}).catch(e=>{$('surgeStatus').textContent=e.message});setInterval(()=>{if(!document.hidden&&!surgeState.failed&&surgeState.settings?.enabled)runSurge(true)},60000);}
mountSurge();

function renderSweepChecks(){const el=$('sweepRows');if(!el)return;let rows=results.flatMap(r=>(r.sweeps??[]).map(x=>({...x,symbol:r.symbol})));el.innerHTML=rows.length?rows.sort((a,b)=>b.closedAt-a.closedAt).slice(0,60).map(x=>`<p><strong>${esc(x.symbol)} · ${x.tf} ${x.label}</strong> · level ${money(x.level)} · ${new Date(x.closedAt).toLocaleString()} <button class="chart-link" data-sweep-coin="${esc(x.symbol)}" data-sweep-mode="${x.tf==='4H'?'ema':'scalp'}">Chart</button></p>`).join(''):'No sweep patterns found in the completed checks. Missing histories are listed in scan details.';}
function mountFakeoutChecks(){const box=document.createElement('section');box.className='panel planner-card';box.innerHTML='<h2>Liquidity sweeps · separate check</h2><p>A wick beyond the previous 20-bar high or low followed by a close back inside. Checked independently of strategy matches on the last three closed 1H and 4H candles. This is candle-pattern evidence, not proof of triggered stop orders or a reversal entry.</p><div id="sweepRows"></div><details><summary>Fakeout filter rules</summary><p>Recommendations require a strong breakout body, a close beyond a volatility buffer, two completed 5m candles after confirmation, no intervening 5m close back inside the original level, and no opposing sweep in the last three 5m candles. The buffer is the largest of 0.1 ATR, two price ticks where available, and 0.01% of price. Crossovers use follow-through timing and the separate sweep check, not a range-break rule. Fresh quote, spread, costs and entry distance checks still apply. No filter can eliminate future failures.</p><p>Raw candle confirmation stays visible when entry checks fail. Final volume alerts arrive no earlier than ten minutes after the hourly close, subject to feed and scan delays. Backtests replay the original strategy rules, not these live filters.</p></details>'; $('surgePanel').after(box);box.addEventListener('click',e=>{const b=e.target.closest('[data-sweep-coin]');if(b)openChart(b.dataset.sweepCoin,b.dataset.sweepMode)});const chartBox=document.createElement('section');chartBox.id='chartGuardStatus';chartBox.className='panel planner-card';$('planSummary').before(chartBox);renderSweepChecks();setInterval(()=>{if(!document.hidden&&chartData?.plan&&!chartData.plan.manual){if(customerDraft?.surge)refreshSurgeGuard();else announceSetup(chartData)}},10000);}
async function refreshSurgeGuard(){const data=chartData,d=customerDraft;if(!data||!d?.surge||data.surgeGuardBusy)return;data.surgeGuardBusy=true;try{const bars=await candles(d.exchange,d.symbol,'5m',90),p={...customerDraftPlan(),mode:'surge',level:d.strategyContext.level},g=StrategySignals.breakoutGuard(p,d.signalAt,bars,data.h);if(chartData!==data||customerDraft!==d)return;data.surgeGuard=g;$('chartGuardStatus').innerHTML='<strong>Volume plan · fakeout and sweep checks</strong><p>'+esc(g.passed?'Closed-candle checks passed; verify live entry price.':g.reason)+'</p>';}catch(e){data.surgeGuard=null;if(chartData===data)$('chartGuardStatus').textContent=e.message}finally{data.surgeGuardBusy=false}}
mountFakeoutChecks();

var customAlertState={alerts:[]},customAlertBusy=false,customAlertSaving=false,pendingCustomCreate=null;
async function customAlertRequest(body){const r=await fetch('/api/custom-alerts',{method:body?'POST':'GET',headers:body?{'content-type':'application/json'}:undefined,body:body?JSON.stringify(body):undefined,cache:'no-store',signal:AbortSignal.timeout(90000)});return accountResponse(r,'Custom alerts');}
function syncCustomAlertCoins(){if(!$('customAlertCoin'))return;const selected=$('customAlertCoin').value;$('customAlertCoin').innerHTML=listings.map(t=>`<option value="${esc(t.symbol)}">${esc(t.base)} · ${esc(t.symbol)}</option>`).join('');$('customAlertCoin').value=listings.some(t=>t.symbol===selected)?selected:listings.find(t=>t.base==='BTC')?.symbol??listings[0]?.symbol??'';previewCustomAlert();}
function previewCustomAlert(autoCoin=false){if(!$('customAlertPreview'))return;const text=$('customAlertText').value;if(autoCoin){const token=text.trim().toUpperCase().replace(/^(TELL|ALERT|NOTIFY) ME (WHEN|IF) /,'').replace(/^THE /,'').match(/^([A-Z0-9]+)\s/)?.[1],coin=listings.find(t=>t.symbol===token||t.base===token||(token==='BITCOIN'&&t.base==='BTC')||(token==='ETHEREUM'&&t.base==='ETH'));if(coin)$('customAlertCoin').value=coin.symbol;}
 $('customAlertMarket').textContent=(exchange()==='delta'?'Delta India':'Shark')+' · '+market();try{const rule=CustomAlertRules.parse(text,{symbol:$('customAlertCoin').value,quote:market()});$('customAlertPreview').textContent='Alert when: '+CustomAlertRules.describe(rule);$('customAlertSave').disabled=customAlertSaving;}catch(e){$('customAlertPreview').textContent=text.trim()?e.message:'Write a price or EMA rule for the selected coin.';$('customAlertSave').disabled=true;}}
function acceptCustomAlerts(d){customAlertState=d;renderCustomAlerts();for(const a of d.alerts??[]){if(a.firedAt&&Date.now()-a.firedAt<=120000){const key='custom:'+a.id+':'+a.firedAt;if(!seenAlerts.has(key)){alertUser(key,a.title,'',{monitor:true,custom:true,symbol:a.rule.symbol,exchange:a.exchange,mode:'scalp'});$('customAlertToastTitle').textContent=a.title;$('customAlertToast').classList.remove('hide');}}}}
function renderCustomAlerts(){if(!$('customAlertList'))return;$('customAlertList').innerHTML=(customAlertState.alerts??[]).map(a=>{const stale=a.checkedAt&&Date.now()-a.checkedAt>60000,state=a.firedAt?'Triggered':!a.enabled?'Paused':a.error?'Check unavailable':stale?'Waiting for fresh check':'Armed',v=a.last;return `<article class="custom-alert-card"><strong>${esc(a.description)}</strong><p>${esc(a.exchange==='delta'?'Delta India':'Shark')} · <b>${state}</b>${a.checkedAt?' · Checked '+new Date(a.checkedAt).toLocaleTimeString():''}</p>${a.firedAt?`<p class="surge-alert"><strong>${esc(a.title)}</strong><small>${new Date(a.firedAt).toLocaleString()}</small></p>`:''}${a.error?`<p class="risk-tag">${esc(a.error)}</p>`:v?`<p class="small-note">Observed price: ${money(v.price,a.rule.quote)}${v.checks.filter(c=>c.type==='ema').map(c=>' · '+c.period+' EMA ('+c.tf+'): '+money(c.threshold,a.rule.quote)).join('')}</p>`:''}<div class="controls">${a.enabled?`<button class="mode" data-custom-action="pause" data-custom-id="${a.id}">Pause</button>`:`<button class="refresh" data-custom-action="rearm" data-custom-id="${a.id}">Re-arm</button>`}<button class="mode" data-custom-action="delete" data-custom-id="${a.id}">Delete</button></div></article>`;}).join('')||'<p>No custom alerts yet. Write your first rule above.</p>';$('customAlertCheck').disabled=customAlertBusy;$('customAlertCheck').textContent=customAlertBusy?'Checking…':'Check now';}
async function checkCustomAlerts(){if(customAlertBusy||document.hidden)return;customAlertBusy=true;renderCustomAlerts();try{let d=await customAlertRequest();acceptCustomAlerts(d);const ids=d.alerts.filter(a=>a.enabled).map(a=>a.id);for(let i=0;i<ids.length;i+=4){if(document.hidden)break;d=await customAlertRequest({action:'check',ids:ids.slice(i,i+4)});acceptCustomAlerts(d);if(d.busy)break;}$('customAlertStatus').textContent=ids.length?(d.busy?'A check is already running. Results will refresh shortly.':'Saved alerts checked. Checks continue about every 20 seconds while the site is open. Multiple batches and sleeping tabs can delay them.'):'No armed alerts. Re-arm or save a rule to start checking.';}catch(e){$('customAlertStatus').textContent=e.message;}finally{customAlertBusy=false;renderCustomAlerts();}}
function mountCustomAlerts(){const panel=document.createElement('section');panel.id='customAlertPanel';panel.className='panel planner-card';panel.innerHTML='<h2>Custom alerts</h2><form id="customAlertForm"><div class="controls"><label>Coin<select id="customAlertCoin" aria-label="Custom alert coin"></select></label><span id="customAlertMarket"></span></div><label for="customAlertText">Write your alert</label><textarea id="customAlertText" rows="3" maxlength="300" placeholder="Tell me when BTC price is below 80000 or below 200 EMA on 5 min time frame"></textarea><p id="customAlertPreview" role="status"></p><div class="controls"><button type="submit" class="refresh" id="customAlertSave" disabled>Save alert</button><button type="button" class="mode" id="customAlertCheck">Check now</button></div></form><p id="customAlertStatus" role="status"></p><details><summary>Examples &amp; how alerts work</summary><p>Examples: “BTC below 80000”; “BTC above 200 EMA on 5m”; “BTC below 80000 or below 200 EMA on 5 min time frame”. Use AND when both conditions must hold, or OR when either can trigger. One coin per alert.</p><p>Price numbers use the selected market currency, shown above. Supported EMA timeframes: 5m, 15m, 30m, 1h, 4h and 1d; periods: 2–500. EMA rules compare a fresh live price against the EMA calculated from completed candles. A rule triggers once, including on its first check if already true. Re-arm it to trigger again.</p><p>Rules and triggered alerts are saved with your site account. Checks run while this site is open; they resume when you return. Conditions that occur only while it is closed may be missed. These custom alerts appear here and in the site alert feed; they do not send WhatsApp messages or place trades.</p></details><div id="customAlertList"></div>';$('strategyView').prepend(panel);const toast=document.createElement('aside');toast.id='customAlertToast';toast.className='custom-alert-toast hide';toast.setAttribute('role','alert');toast.innerHTML='<strong id="customAlertToastTitle"></strong><button type="button" class="mode" id="customAlertDismiss">Dismiss</button>';document.body.append(toast);$('customAlertDismiss').addEventListener('click',()=>toast.classList.add('hide'));$('customAlertText').addEventListener('input',()=>previewCustomAlert(true));$('customAlertCoin').addEventListener('change',()=>previewCustomAlert());$('customAlertCheck').addEventListener('click',checkCustomAlerts);$('customAlertForm').addEventListener('submit',async e=>{e.preventDefault();if(customAlertSaving)return;customAlertSaving=true;previewCustomAlert();const text=$('customAlertText').value;try{const payload={action:'create',exchange:exchange(),quote:market(),symbol:$('customAlertCoin').value,text},signature=JSON.stringify(payload);if(pendingCustomCreate?.signature!==signature)pendingCustomCreate={signature,requestId:crypto.randomUUID()};const d=await customAlertRequest({...payload,requestId:pendingCustomCreate.requestId});pendingCustomCreate=null;acceptCustomAlerts(d);if($('customAlertText').value===text)$('customAlertText').value='';$('customAlertStatus').textContent='Alert saved. Checking the condition now.';await checkCustomAlerts();}catch(e){$('customAlertStatus').textContent=e.message;}finally{customAlertSaving=false;previewCustomAlert();}});panel.addEventListener('click',async e=>{const b=e.target.closest('[data-custom-action]');if(!b)return;const a=customAlertState.alerts.find(a=>a.id===b.dataset.customId);if(!a)return;b.disabled=true;try{acceptCustomAlerts(await customAlertRequest({action:b.dataset.customAction,id:a.id,version:a.version}));if(b.dataset.customAction==='rearm')await checkCustomAlerts();}catch(e){$('customAlertStatus').textContent=e.message;customAlertRequest().then(acceptCustomAlerts).catch(()=>{});}finally{b.disabled=false;}});syncCustomAlertCoins();checkCustomAlerts();setInterval(()=>{renderCustomAlerts();checkCustomAlerts();},20000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkCustomAlerts();});window.addEventListener('online',checkCustomAlerts);}
mountCustomAlerts();

// Keep independent setup tools in separate, labelled views without resetting their state.
function organizeSetupWorkspace(){
 const root=$('strategyView'),custom=$('customAlertPanel'),surge=$('surgePanel'),alerts=$('alertCenter'),sweeps=$('sweepRows').parentElement,news=root.querySelector('.news');
 const scanner=document.createElement('section');scanner.id='setupScanner';
 for(const node of [...root.children])if(![custom,surge,alerts,sweeps,news].includes(node))scanner.append(node);
 const views=[['scanner','Market scanner',scanner],['surge','Top 20 volume',surge],['sweeps','Liquidity sweeps',sweeps],['custom','Custom alerts',custom],['history','Alert history',alerts],['news','News',news]];
 const nav=document.createElement('nav');nav.className='setup-navigation';nav.setAttribute('aria-label','Setup tools');
 const select=key=>{for(const [id,,panel] of views){panel.classList.toggle('hide',id!==key);const button=nav.querySelector('[data-setup-view="'+id+'"]');button.classList.toggle('active',id===key);if(id===key)button.setAttribute('aria-current','page');else button.removeAttribute('aria-current');}};
 for(const [key,label,panel] of views){panel.classList.add('setup-section');const button=document.createElement('button');button.type='button';button.className='mode';button.dataset.setupView=key;button.textContent=label;button.addEventListener('click',()=>select(key));nav.append(button);root.append(panel);}
 root.prepend(nav);select('scanner');
}
organizeSetupWorkspace();

async function showDeltaConnectionRoute(){
 const el=document.createElement('p');el.className='settings-status';el.id='deltaRouteStatus';$('deltaSettings').append(el);
 try{const r=await fetch('/api/delta-desk/connection-info',{cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Connection settings unavailable');
 el.textContent=d.fixedIpConfigured?'Fixed-IP server configured. '+(d.outboundIp?'Allowlist '+d.outboundIp+' once in Delta India. ':'')+'Your encrypted connection stays saved until you disconnect. Account refresh verifies access.':location.hostname==='localhost'?'Local connection: Delta must allowlist this computer’s public IP. Your connection stays saved.':'Hosted fixed-IP connection is not configured yet. Delta requires an allowlisted server IP. Setup is needed once; the saved account connection then persists across visits.';
 }catch(e){el.textContent=e.message;}
}
showDeltaConnectionRoute();

// Telegram content is displayed as plain text and never used as a trade instruction.
(()=>{
 const news=document.querySelector('.news');if(!news)return;
 const local=location.hostname==='localhost',panel=document.createElement('section');panel.id='telegramNews';
 panel.innerHTML='<div class="section-head"><h3>News · @lmwmnews</h3><a class="telegram-primary" href="/telegram-connect">'+(local?'Connect / manage Telegram':'Set up Telegram news')+'</a></div>'+
 (local?'<p class="small-note">Live feed from your Telegram connection. This screen checks for received posts every second while visible.</p>':'<div class="telegram-setup-note"><p><strong>Connect Telegram in the Windows app to receive live news.</strong></p><p>Start Market Radar on your computer, then <a href="http://localhost:8787/telegram-connect" target="_blank" rel="noopener noreferrer">open the Telegram connection screen ↗</a>. Read incoming news in the local app after signing in.</p><p class="small-note">This hosted page only offers a public preview, which may be unavailable. It does not share your local Telegram session.</p></div>')+
 '<p><a href="https://t.me/lmwmnews" target="_blank" rel="noopener noreferrer">Open channel in Telegram ↗</a></p><p id="telegramStatus" role="status">Checking '+(local?'Telegram connection':'public preview')+'…</p><div id="telegramRows"></div>';
 news.prepend(panel);let busy=false,last='';
 async function refresh(){
  if(busy||document.hidden)return;busy=true;
  try{
   const r=await fetch('/api/telegram-news',{cache:'no-store',signal:AbortSignal.timeout(18000)}),d=await r.json();
   if(!r.ok||!d||!Array.isArray(d.articles)||typeof d.available!=='boolean')throw Error('Invalid feed response');
   const articles=d.articles.filter(x=>x&&/^https:\/\/t\.me\/lmwmnews\/\d+$/.test(x.url)&&typeof x.title==='string'&&Number.isFinite(Date.parse(x.at)));
   const stale=!d.available&&articles.length?' Showing posts from the last successful update.':'';
   $('telegramStatus').textContent=d.local?(d.available?'Connected · '+articles.length+' recent posts · screen checks every second'+(d.lastEventAt?' · Last update '+new Date(d.lastEventAt).toLocaleTimeString():''):(d.error||({disconnected:'Not connected. Click Connect / manage Telegram to sign in.',code:'Sign-in in progress. Enter the code on the Telegram connection screen.',password:'Sign-in in progress. Enter your two-step password on the Telegram connection screen.',connecting:'Connecting to Telegram…',reconnecting:'Connection interrupted. Reconnecting…'}[d.state]||'Telegram connection needs attention. Open Connect / manage Telegram.'))+stale):(d.available?'Public preview · checked '+new Date(d.checkedAt).toLocaleTimeString():'Public preview unavailable. Use Set up Telegram news above for the connected feed.')+stale;
   const rows=JSON.stringify(articles);
   panel.dataset.connected=String(d.available&&!!d.local);
   if(rows!==last){last=rows;$('telegramRows').innerHTML=TelegramPosts.renderFeed(articles)+(d.available&&!articles.length?'<p>Connected. Waiting for channel posts.</p>':'')}

  }catch{$('telegramStatus').textContent='News connection interrupted. '+(last&&last!=='[]'?'Displayed posts are from the last successful update.':local?'Check that your Market Radar server is running.':'Use Set up Telegram news above or open the channel directly.')}
  finally{busy=false}
 }
 refresh();setInterval(refresh,local?1000:60000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});
})();
